import{_ as d,c as r,j as a,a as o,G as l,al as i,B as n,o as h}from"./chunks/framework.D3pXwl8O.js";const m=JSON.parse('{"title":"Holybro Kakute H743-Wing","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/kakuteh7-wing.md","filePath":"uk/flight_controller/kakuteh7-wing.md"}'),s={name:"uk/flight_controller/kakuteh7-wing.md"};function p(u,t,c,b,f,g){const e=n("Badge");return h(),r("div",null,[t[0]||(t[0]=a("h1",{id:"holybro-kakute-h743-wing",tabindex:"-1"},[o("Holybro Kakute H743-Wing "),a("a",{class:"header-anchor",href:"#holybro-kakute-h743-wing","aria-label":'Permalink to "Holybro Kakute H743-Wing"'},"​")],-1)),l(e,{type:"tip",text:"PX4 v1.16"}),t[1]||(t[1]=i('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://holybro.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <a href="https://holybro.com/products/kakute-h743-wing" target="_blank" rel="noreferrer">Holybro Kakute H743 Wing</a> is a fully featured flight controller specifically aimed at fixed-wing and VTOL applications. It has the STM32 H743 Processor running at 480 MHz and CAN Bus support, along with dual camera support &amp; switch, ON/OFF Pit Switch, 5V, 6V/8V, 9V/12 BEC, and plug-and-play GPS, CAN, I2C ports.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Плату можна придбати в одному з наступних магазинів (наприклад):</p><ul><li><a href="https://holybro.com/products/kakute-h743-wing" target="_blank" rel="noreferrer">Holybro</a></li></ul><h2 id="конектори-та-контакти" tabindex="-1">Конектори та контакти <a class="header-anchor" href="#конектори-та-контакти" aria-label="Permalink to &quot;Конектори та контакти&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pin</th><th>Функція</th><th>PX4 default</th></tr></thead><tbody><tr><td>GPS 1</td><td>USART1 and I2C1</td><td>GPS1</td></tr><tr><td>R2, T2</td><td>USART2 RX and TX</td><td>GPS2</td></tr><tr><td>R3, T3</td><td>USART3 RX and TX</td><td>TELEM1</td></tr><tr><td>R5, T5</td><td>USART5 RX and TX</td><td>TELEM2</td></tr><tr><td>R6, T6</td><td>USART6 RX and TX</td><td>RC (PPM, SBUS, etc.) input</td></tr><tr><td>R7, T7, RTS, CTS</td><td>UART7 RX and TX with flow control</td><td>TELEM3</td></tr><tr><td>R8, T8</td><td>UART8 RX and TX</td><td>Консоль</td></tr><tr><td>Buz-, Buz+</td><td>Piezo buzzer</td><td></td></tr><tr><td>M1 to M14</td><td>Motor signal outputs</td><td></td></tr></tbody></table><h2 id="bootloader" tabindex="-1">PX4 Bootloader Update <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;PX4 Bootloader Update {#bootloader}&quot;">​</a></h2><p>The board comes pre-installed with <a href="https://github.com/betaflight/betaflight/wiki" target="_blank" rel="noreferrer">Betaflight</a>. Before the PX4 firmware can be installed, the <em>PX4 bootloader</em> must be flashed. Download the <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/flight_controller/kakuteh7-wing/holybro_kakuteh7-wing_bootloader.hex" target="_blank" rel="noreferrer">holybro_kakuteh7-wing.hex</a> bootloader binary and read <a href="./../advanced_config/bootloader_update_from_betaflight.html">this page</a> for flashing instructions.</p><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make holybro_kakuteh7-wing_default</span></span></code></pre></div><h2 id="встановлення-прошивки-px4" tabindex="-1">Встановлення прошивки PX4 <a class="header-anchor" href="#встановлення-прошивки-px4" aria-label="Permalink to &quot;Встановлення прошивки PX4&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>KakuteH7-wing is supported in PX4 v1.16 or newer. До випуску вам потрібно буде вручну зібрати та встановити прошивку.</p></div><p>Прошивку можна встановити вручну будь-якими звичайними способами:</p><ul><li><p>Збудуйте та завантажте джерело:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make holybro_kakuteh7-wing_default upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware.html">Load the firmware</a> using <em>QGroundControl</em>. Ви можете використовувати або готове вбудоване програмне забезпечення, або власне користувацьке програмне забезпечення.</p></li></ul><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th><th>Default function</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS 1</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>R2, T2</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>R3, T3</td><td>TELEM1</td></tr><tr><td>UART5</td><td>/dev/ttyS3</td><td>R5, T5</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td>R6, (T6)</td><td>Вхід RC</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>R7, T7, RTS, CTS</td><td>TELEM3</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>R8, T8</td><td>Консоль</td></tr></tbody></table><h2 id="відладочнии-порт" tabindex="-1">Відладочний порт <a class="header-anchor" href="#відладочнии-порт" aria-label="Permalink to &quot;Відладочний порт&quot;">​</a></h2><h3 id="системна-консоль" tabindex="-1">Системна консоль <a class="header-anchor" href="#системна-консоль" aria-label="Permalink to &quot;Системна консоль&quot;">​</a></h3><p>UART8 RX and TX are configured for use as the <a href="./../debug/system_console.html">System Console</a>.</p>',22))])}const T=d(s,[["render",p]]);export{m as __pageData,T as default};
